import { expect, expectStatus, test } from "../../fixtures";

test("after a replacement, only the new document waits for review", { tag: "@LIF-05" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review; reviewer approves insurance and contract, rejects the W-9.
  const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
  const reviewer = await apiAs("reviewer");
  const member = await apiAs("member");

  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
      data: { decision: "approve" },
    }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
      data: { decision: "approve" },
    }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "W-9 is unreadable" },
    }),
    200,
  );

  // Act: upload a replacement W-9, wait for extraction, and submit the vendor again.
  const newW9 = await factory.upload(vendor.id, "w9", "w9.txt", "member");
  await expect
    .poll(
      async () =>
        (await expectStatus<{ status: string }>(await member.get(`/api/documents/${newW9.id}`), 200)).status,
      { message: "replacement W-9 is extracted", timeout: 30_000 },
    )
    .toBe("extracted");
  const submitted = await expectStatus<{ status: string }>(
    await member.post(`/api/vendors/${vendor.id}/submit`),
    200,
  );

  // Assert: the vendor is back in review, and only the new W-9 extraction is pending.
  expect(submitted.status).toBe("in_review");

  const queue = await expectStatus<
    Array<{ vendor_id: string; extractions: Array<{ kind: string; status: string }> }>
  >(await reviewer.get("/api/review-queue"), 200);
  const item = queue.find((entry) => entry.vendor_id === vendor.id);
  expect(item, "vendor appears in the review queue").toBeDefined();
  const pending = (item?.extractions ?? []).filter((e) => e.status === "pending_review");
  expect(pending.map((e) => e.kind)).toEqual(["w9"]);
});
